// === Tab: mySketch ===
// Attractor_2.0

let N = 4000 ; let H = 20 ;
let X[] = new Array(N) ; let Y[] = new Array(N) ; let G[] = new Array(N) ;
let I ; let NX ; let NY ; let A ; let S ; let M ; let dA ; let dM ; 

function setup(){
  createCanvas(600, 600) ; noSmooth() ; background(0) ; stroke(255,0,0) ; fill(0,0,0,10) ;
  for ( I = 0 ; I < N ; I++ ){
    X[I] = random(-H,+H) ; Y[I] = random(-H,+H) ; 
    G[I] = (M*X[I])+((2*(1-M)*X[I]*X[I])/(1+(X[I]*X[I]))) ;
  }
  A = +0.00905 ; S = +0.05 ; M = -0.81625 ; dA = -0.0000005 ; dM = +0.0001525 ;  
} // setup()

function draw(){
  rect(-1,-1,601,601) ;
  for ( I = 0 ; I < N ; I++ ){
    NX = Y[I] + (A*Y[I]*(1-(S*Y[I]*Y[I]))) + G[I] ;
    G[I] = (M*NX)+((2*(1-M)*NX*NX)/(1+(NX*NX))) ;
    NY = -X[I] + G[I] ;
    point(X[I]*(300/H)+275,Y[I]*(300/H)+300) ;
    X[I] = NX ; Y[I] = NY ;
  }
  A = A + dA ; M = M + dM ; if ( A < 0.0050 || A > 0.0091 ){ dA = -dA ; dM = -dM ; }
} // draw()

